1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.web.bind.annotation.RequestBody;
9	
10	/**
11	 * Rejects a create-owner request that is missing or blank in any of firstName, lastName,
12	 * address, city or telephone, before {@link BuildOwner} runs. Runs first so an incomplete
13	 * body is a 400 naming the offending fields. Also normalizes the telephone into E.164 form
14	 * (see {@link OwnerTelephone}), rejecting otherwise with a 400; the normalized value is
15	 * stored on the body so it is persisted and returned.
16	 * When an {@code email} is present it must be a syntactically valid address and is stored
17	 * lower-cased (rejected with 400 otherwise); an absent email is allowed.
18	 * Publishes the validated body for later steps.
19	 */
20	public class ValidateOwnerFields {
21	
22	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
23	            throws MissingOwnerFieldsException, InvalidOwnerTelephoneException, InvalidOwnerEmailException {
24	        // Normalize the address up front so the required-field check below rejects an address that
25	        // is blank after normalization, and the persisted/returned value is the normalized form.
26	        request.setAddress(OwnerAddress.normalize(request.getAddress()));
27	        List<String> missing = new ArrayList<>();
28	        checkField("firstName", request.getFirstName(), missing);
29	        checkField("lastName", request.getLastName(), missing);
30	        checkField("address", request.getAddress(), missing);
31	        checkField("city", request.getCity(), missing);
32	        checkField("telephone", request.getTelephone(), missing);
33	        if (!missing.isEmpty()) {
34	            throw new MissingOwnerFieldsException(missing);
35	        }
36	        request.setTelephone(OwnerTelephone.toE164(request.getTelephone()));
37	        OwnerEmail.normalize(request);
38	        validated.set(request);
39	    }
40	
41	    private static void checkField(String name, String value, List<String> missing) {
42	        if (value == null || value.isBlank()) {
43	            missing.add(name);
44	        }
45	    }
46	}
