1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Rejects a create-owner request whose E.164 telephone is already used by any other owner,
10	 * responding 409. Runs after {@link ValidateOwnerFields} (which normalizes the telephone to
11	 * E.164 form) and before {@link BuildOwner}, comparing E.164 values against every existing
12	 * owner.
13	 */
14	public class EnsureUniqueOwnerTelephone {
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws DuplicateOwnerTelephoneException {
18	        String telephone = OwnerTelephone.canonical(request.getTelephone());
19	        for (Owner existing : ownerRepository.findAll()) {
20	            if (telephone.equals(OwnerTelephone.canonical(existing.getTelephone()))) {
21	                throw new DuplicateOwnerTelephoneException(telephone);
22	            }
23	        }
24	    }
25	}
