1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	/**
11	 * Rejects a create-owner request whose last name and address match an existing owner,
12	 * responding 409. Names and addresses are compared case-insensitively with collapsed
13	 * whitespace. A request that sets {@code sharesHousehold} true bypasses the check so
14	 * genuine housemates can be registered. Runs after {@link ValidateOwnerFields} (which
15	 * has already ensured last name and address are present) and before {@link BuildOwner}.
16	 */
17	public class EnsureUniqueOwnerHousehold {
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws DuplicateOwnerHouseholdException {
21	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
22	            return;
23	        }
24	        String lastName = normalize(request.getLastName());
25	        String address = normalizeAddress(request.getAddress());
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (lastName.equals(normalize(existing.getLastName()))
28	                    && address.equals(normalizeAddress(existing.getAddress()))) {
29	                throw new DuplicateOwnerHouseholdException(request.getLastName(), request.getAddress());
30	            }
31	        }
32	    }
33	
34	    /** Lower-cases and collapses runs of whitespace to a single space, trimming the ends. */
35	    private static String normalize(String value) {
36	        if (value == null) {
37	            return "";
38	        }
39	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
40	    }
41	
42	    /** Address comparison uses the same normalized form the endpoint stores (see {@link OwnerAddress}). */
43	    private static String normalizeAddress(String value) {
44	        String normalized = OwnerAddress.normalize(value);
45	        return normalized == null ? "" : normalized;
46	    }
47	}
