1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	
9	/**
10	 * Assigns the {@code customerCode} to a newly built owner, formatted
11	 * {@code <CITY3>-<LAST3>-<NNNN>} where {@code CITY3} is the upper-cased first three
12	 * letters of the city, {@code LAST3} is the upper-cased first three letters of the last
13	 * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than
14	 * the number of owners already in that city (e.g. {@code SYD-SMI-0007}).
15	 *
16	 * <p>Runs after {@link BuildOwner} and before {@link SaveOwner}, so the owner being
17	 * created is not yet counted: {@code NNNN} = existing owners in the city + 1. Mutates the
18	 * owner in place (the same object {@link SaveOwner} persists).
19	 */
20	public class AssignOwnerCustomerCode {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        String city = owner.getCity() == null ? "" : owner.getCity();
24	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
25	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
26	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
27	        int sequence = (int) ownerRepository.findAll().stream()
28	                .filter(o -> city.equals(o.getCity()))
29	                .count() + 1;
30	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
31	    }
32	}
