1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.ArrayList;
7	import java.util.List;
8	import java.util.Locale;
9	
10	import net.officefloor.plugin.variable.Val;
11	import org.springframework.samples.petclinic.model.Owner;
12	import org.springframework.samples.petclinic.repository.OwnerRepository;
13	
14	/**
15	 * Assigns a shared {@code householdId} to a newly built owner that shares a household
16	 * with one or more existing owners (same last name and address, compared
17	 * case-insensitively with collapsed whitespace — the same rule as
18	 * {@link EnsureUniqueOwnerHousehold}).
19	 *
20	 * <p>Runs after {@link BuildOwner} and before {@link SaveOwner}. Reaching this step with
21	 * a matching existing owner means the request set {@code sharesHousehold} true (otherwise
22	 * {@link EnsureUniqueOwnerHousehold} would already have rejected it), so genuine
23	 * housemates are grouped under one identifier. The identifier is derived deterministically
24	 * from the normalized last name and address, so every member of a household resolves to
25	 * the same value regardless of creation order; existing members that predate the household
26	 * are back-filled with it. An owner with no housemate keeps a {@code null} householdId.
27	 */
28	public class AssignOwnerHousehold {
29	
30	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
31	        String lastName = normalize(owner.getLastName());
32	        String address = normalizeAddress(owner.getAddress());
33	        List<Owner> housemates = new ArrayList<>();
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (lastName.equals(normalize(existing.getLastName()))
36	                    && address.equals(normalizeAddress(existing.getAddress()))) {
37	                housemates.add(existing);
38	            }
39	        }
40	        if (housemates.isEmpty()) {
41	            return; // no shared household
42	        }
43	        String householdId = householdId(lastName, address);
44	        owner.setHouseholdId(householdId);
45	        for (Owner mate : housemates) {
46	            if (mate.getHouseholdId() == null || mate.getHouseholdId().isBlank()) {
47	                mate.setHouseholdId(householdId);
48	                ownerRepository.save(mate);
49	            }
50	        }
51	    }
52	
53	    /** Stable 12-char upper-hex identifier derived from the normalized household key. */
54	    private static String householdId(String lastName, String address) {
55	        String key = lastName + "\n" + address;
56	        try {
57	            byte[] digest = MessageDigest.getInstance("SHA-256")
58	                    .digest(key.getBytes(StandardCharsets.UTF_8));
59	            StringBuilder sb = new StringBuilder(12);
60	            for (int i = 0; i < 6; i++) {
61	                sb.append(String.format("%02X", digest[i]));
62	            }
63	            return sb.toString();
64	        }
65	        catch (NoSuchAlgorithmException e) {
66	            throw new IllegalStateException(e);
67	        }
68	    }
69	
70	    /** Lower-cases and collapses runs of whitespace to a single space, trimming the ends. */
71	    private static String normalize(String value) {
72	        if (value == null) {
73	            return "";
74	        }
75	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
76	    }
77	
78	    /** Address comparison uses the same normalized form the endpoint stores (see {@link OwnerAddress}). */
79	    private static String normalizeAddress(String value) {
80	        String normalized = OwnerAddress.normalize(value);
81	        return normalized == null ? "" : normalized;
82	    }
83	}
