1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	/**
4	 * Normalizes an owner telephone number into E.164 form.
5	 *
6	 * <p>Rules: strip spaces, dashes and brackets. If a leading {@code '+'} (and therefore an
7	 * explicit country code) is present it is kept as-is. Otherwise the default country code
8	 * {@code +61} is assumed and a single leading {@code '0'} is dropped from the national digits.
9	 * The result must carry 8 to 15 digits after the {@code '+'}. Anything that cannot form a
10	 * valid E.164 number raises {@link InvalidOwnerTelephoneException} so the endpoint responds 400.
11	 *
12	 * <p>So {@code "0412 345 678"} becomes {@code "+61412345678"} and {@code "+64 21 123 456"}
13	 * becomes {@code "+6421123456"}.
14	 */
15	final class OwnerTelephone {
16	
17	    /** Default country code assumed when the input carries no explicit {@code '+'} prefix. */
18	    private static final String DEFAULT_COUNTRY_CODE = "61";
19	
20	    private static final int MIN_DIGITS = 8;
21	
22	    private static final int MAX_DIGITS = 15;
23	
24	    private OwnerTelephone() {
25	    }
26	
27	    /**
28	     * Convert a raw telephone string into E.164 form, or throw when it cannot form a valid one.
29	     */
30	    static String toE164(String raw) throws InvalidOwnerTelephoneException {
31	        if (raw == null) {
32	            throw new InvalidOwnerTelephoneException("null");
33	        }
34	        // Strip spaces, dashes and brackets.
35	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
36	        boolean explicitCountryCode = cleaned.startsWith("+");
37	        String digits = explicitCountryCode ? cleaned.substring(1) : cleaned;
38	        if (digits.isEmpty() || !digits.chars().allMatch(Character::isDigit)) {
39	            throw new InvalidOwnerTelephoneException(raw);
40	        }
41	        String e164Digits;
42	        if (explicitCountryCode) {
43	            e164Digits = digits;
44	        }
45	        else {
46	            // No explicit country code: assume the default and drop one leading national '0'.
47	            String national = digits.startsWith("0") ? digits.substring(1) : digits;
48	            e164Digits = DEFAULT_COUNTRY_CODE + national;
49	        }
50	        if (e164Digits.length() < MIN_DIGITS || e164Digits.length() > MAX_DIGITS) {
51	            throw new InvalidOwnerTelephoneException(raw);
52	        }
53	        return "+" + e164Digits;
54	    }
55	
56	    /**
57	     * Canonical E.164 form for comparison, falling back to a digits-only form for values that
58	     * cannot form a valid E.164 number (e.g. legacy data).
59	     */
60	    static String canonical(String raw) {
61	        try {
62	            return toE164(raw);
63	        }
64	        catch (InvalidOwnerTelephoneException ex) {
65	            return raw == null ? "" : raw.replaceAll("\\D", "");
66	        }
67	    }
