2	
3	import java.util.Locale;
4	import java.util.Map;
5	
6	/**
7	 * Normalization for the owner {@code address}, applied whenever an owner is created.
8	 *
9	 * <p>Rules: trim the ends and collapse runs of whitespace to a single space, upper-case, and
10	 * expand common street-type abbreviations ({@code ST -> STREET}, {@code RD -> ROAD},
11	 * {@code AVE -> AVENUE}). So {@code "  12  main  st "} becomes {@code "12 MAIN STREET"} and
12	 * {@code "7 elm ave"} becomes {@code "7 ELM AVENUE"}.
13	 *
14	 * <p>The normalized value is what {@link ValidateOwnerFields} stores on the request (so it is
15	 * persisted and returned) and is the form used for every address comparison — the required-field
16	 * check (a value blank after normalization is rejected), household duplicate detection
17	 * ({@link EnsureUniqueOwnerHousehold}) and the shared household id ({@link AssignOwnerHousehold}).
18	 * The transformation is idempotent, so re-normalizing an already-normalized value is a no-op.
19	 */
20	final class OwnerAddress {
21	
22	    /** Common street-type abbreviations expanded to their full (upper-cased) form. */
23	    private static final Map<String, String> ABBREVIATIONS = Map.of(
24	            "ST", "STREET",
25	            "RD", "ROAD",
26	            "AVE", "AVENUE");
27	
28	    private OwnerAddress() {
29	    }
30	
31	    /**
32	     * Normalize a raw address; {@code null} stays {@code null} and a value that is only whitespace
33	     * normalizes to the empty string.
34	     */
35	    static String normalize(String raw) {
36	        if (raw == null) {
37	            return null;
38	        }
39	        String collapsed = raw.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
40	        if (collapsed.isEmpty()) {
41	            return "";
42	        }
43	        String[] tokens = collapsed.split(" ");
44	        StringBuilder sb = new StringBuilder(collapsed.length());
45	        for (int i = 0; i < tokens.length; i++) {
46	            if (i > 0) {
47	                sb.append(' ');
48	            }
49	            sb.append(ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
50	        }
51	        return sb.toString();
52	    }
53	}
